SELECT percentile_cont(0.25) within GROUP (ORDER BY value) AS p25, percentile_cont(0.75) within GROUP (ORDER BY value) AS p75, percentile_cont(0.50) within GROUP (ORDER BY value) AS p50, MIN(value) AS min_value, MAX(value) AS max_value FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN admissions ON labevents.subject_id = admissions.subject_id WHERE patients.gender = 'F' AND patients.anchor_age = 41 AND admissions.admission_type_id = 757071 AND labevents.itemid = 871600 AND labevents.value > 1000;